#!/usr/bin/env python3
from __future__ import annotations

import argparse
import hashlib
import json
from pathlib import Path

from backend import model_kernel as kernel


def reject_pairs(pairs):
    out = {}
    for key, value in pairs:
        if key in out:
            raise ValueError(f"duplicate key: {key}")
        out[key] = value
    return out


def canonical(value):
    return json.dumps(value, sort_keys=True, separators=(",", ":"),
                      ensure_ascii=False).encode("utf-8")


def sha_bytes(value):
    return hashlib.sha256(value).hexdigest()


def load_exact(path):
    raw = path.read_bytes()
    assert not raw.endswith(b"\n")
    value = json.loads(raw.decode("utf-8"), object_pairs_hook=reject_pairs)
    assert canonical(value) == raw
    return raw, value


def count_iterative(value):
    nodes = 0
    depth = 0
    stack = [(value, 1)]
    while stack:
        item, level = stack.pop()
        nodes += 1
        depth = max(depth, level)
        if isinstance(item, dict):
            stack.extend((child, level + 1) for child in item.values())
        elif isinstance(item, list):
            stack.extend((child, level + 1) for child in item)
    return nodes, depth


def count_refs(value):
    total = 0
    stack = [value]
    while stack:
        item = stack.pop()
        if isinstance(item, dict):
            if set(item) == {"$ref"}:
                total += 1
            else:
                stack.extend(item.values())
        elif isinstance(item, list):
            stack.extend(item)
    return total


def resolve(value, objects, lineage=()):
    if isinstance(value, dict) and set(value) == {"$ref"}:
        key = value["$ref"]
        assert key in objects and key not in lineage
        return resolve(objects[key]["value"], objects, lineage + (key,))
    if isinstance(value, dict):
        return {key: resolve(item, objects, lineage) for key, item in value.items()}
    if isinstance(value, list):
        return [resolve(item, objects, lineage) for item in value]
    return value


def count_premises(value):
    count = 0
    stack = [value]
    while stack:
        item = stack.pop()
        if isinstance(item, dict):
            count += int("premise_id" in item)
            stack.extend(item.values())
        elif isinstance(item, list):
            stack.extend(item)
    return count


def count_trace(value):
    count = 0
    stack = [value]
    while stack:
        item = stack.pop()
        if isinstance(item, dict):
            for key, child in item.items():
                if key in {"corner_evaluations", "contributors", "trace"}:
                    count += len(child) if isinstance(child, list) else 1
                stack.append(child)
        elif isinstance(item, list):
            stack.extend(item)
    return count


def input_metrics(value, objects):
    wire = canonical(value)
    wn, wd = count_iterative(value)
    refs = count_refs(value)
    expanded = resolve(value, objects)
    rn, rd = count_iterative(expanded)
    return {"premises": count_premises(expanded), "references": refs,
            "resolution_charge_nodes": rn - wn + refs,
            "resolved_bytes": len(canonical(expanded)), "resolved_depth": rd,
            "resolved_nodes": rn, "wire_bytes": len(wire), "wire_depth": wd,
            "wire_nodes": wn}


def output_metrics(value):
    nodes, depth = count_iterative(value)
    return {"output_bytes": len(canonical(value)), "output_depth": depth,
            "output_nodes": nodes, "trace_rows": count_trace(value)}


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("package", type=Path)
    ap.add_argument("manifest", type=Path)
    args = ap.parse_args()
    package_raw, package = load_exact(args.package)
    manifest_raw, manifest = load_exact(args.manifest)
    assert manifest["package_sha256"] == sha_bytes(package_raw)
    assert manifest["package_bytes"] == len(package_raw)
    assert manifest["design_sha256"] == package["design_sha256"]
    objects = package["objects"]
    assert len(objects) == len(manifest["object_index"])
    for key, entry in objects.items():
        assert key == sha_bytes(canonical(entry["value"]))
        assert entry["bytes"] == len(canonical(entry["value"]))
        assert manifest["object_index"][key] == {"bytes": entry["bytes"], "kind": entry["kind"]}
    for entry in objects.values():
        resolve(entry["value"], objects)

    roles = {row["role_id"]: row for row in manifest["role_inventory"]}
    assert len(roles) == 73
    assert package["scope"] == {"decision_count": 22, "primary_cases": 10,
        "refusals": 11, "required_mutants": 8, "resource_probes": 26,
        "semantic_roles": 36, "total_roles": 73}
    inventory = objects[package["corpus"]["roles_sha256"]]["value"]
    assert len(inventory) == 73
    decision_inventory = next(x["value"] for x in objects.values()
                              if x["kind"] == "decision_inventory")
    assert len(decision_inventory) == 22
    assert len({x["decision_id"] for x in decision_inventory}) == 22
    base_world = next(x["value"] for x in objects.values()
                      if x["kind"] == "application_world" and x["value"]["world_id"] == "W0")
    for decision in decision_inventory:
        if decision["family"] == "raw_prediction":
            for path in decision["semantic_inputs"]:
                if path.startswith("effects/"):
                    assert path.split("/", 1)[1] in base_world["effects"]
                if path.startswith("timing/"):
                    assert path.split("/", 1)[1] in base_world["timing"]
                if path.startswith("preconditions/"):
                    assert path.split("/", 1)[1] in base_world["preconditions"]
                if path.startswith("invariants/"):
                    assert path.split("/", 1)[1] in base_world["invariants"]

    expected_outputs = {row["expected_output_sha256"] for row in roles.values()}
    for row in roles.values():
        inp = objects[row["input_sha256"]]["value"]
        assert not (set_refs(inp) & expected_outputs)
        assert input_metrics(inp, objects) == row["input_metrics"]
        out = objects[row["expected_output_sha256"]]["value"]
        assert output_metrics(out) == row["output_metrics"]

    def out(role_id):
        return objects[roles[role_id]["expected_output_sha256"]]["value"]

    def reeval(case_id):
        value = out(case_id + "/review")
        return {x["decision_id"] for x in value["result"]["rows"]
                if x["disposition"] == "requires_reevaluation"}

    raw_ids = {f"D-RAW-{h}-{a}" for h in ("HH", "HF") for a in ("a0", "aH", "aF", "aHF")}
    tgt_ids = {x.replace("D-RAW", "D-TGT") for x in raw_ids}
    feas_ids = {f"D-FEAS-{a}" for a in ("a0", "aH", "aF", "aHF")}
    assert reeval("C7") == tgt_ids | feas_ids | {"D-SELECT"}
    assert not (reeval("C7") & raw_ids)
    c0p, c7p = out("C0/projection")["result"], out("C7/projection")["result"]
    assert c0p["raw_predictions"] == c7p["raw_predictions"]
    assert {x["relation"] for x in c7p["target_assessments"]} == {"incompatible"}
    assert c7p["selection"]["status"] == "no_feasible_action_in_supplied_set"

    c1 = out("C1/review")["result"]["rows"]
    assert len([x for x in c1 if x["disposition"] == "requires_reevaluation"]) == 21
    assert {x["decision_id"] for x in c1 if x["expected_value_changed"] and x["decision_id"].startswith("D-RAW")} == {"D-RAW-HH-a0", "D-RAW-HH-aF"}
    assert reeval("C2") == set() and reeval("C3") == {"D-HOT"}
    assert reeval("C5") == {"D-SELECT"}
    assert out("C5/projection")["result"]["raw_predictions"] == c0p["raw_predictions"]
    assert out("C5/projection")["result"]["selection"]["selected"] == ["aH", "aHF"]

    m1 = out("M1/projection")["result"]
    got = {x["decision_id"]: (x["outcome"]["lower"], x["outcome"]["upper"])
           for x in m1["raw_predictions"]}
    wanted = {"D-RAW-HH-a0": ("40", "44"), "D-RAW-HH-aH": ("30", "34"),
              "D-RAW-HH-aF": ("40", "44"), "D-RAW-HH-aHF": ("30", "34"),
              "D-RAW-HF-a0": ("34", "38"), "D-RAW-HF-aH": ("34", "38"),
              "D-RAW-HF-aF": ("30", "34"), "D-RAW-HF-aHF": ("30", "34")}
    assert got == wanted
    assert {x["relation"] for x in m1["target_assessments"]} == {"incompatible", "possible_not_guaranteed"}
    assert out("C6/projection")["result"]["selection"]["status"] == "unknown"
    assert out("M2/review")["diagnostics"][0]["code"] == "effect_edition_mismatch"
    assert out("M2/projection")["diagnostics"][0]["code"] == "effect_edition_mismatch"
    for cid in ("C4", "M3", "M5", "M6", "M7"):
        assert out(cid + "/projection")["result"]["selection"]["status"] == "unknown"
    assert out("C9/projection")["result"]["selection"]["status"] == "no_feasible_action_in_supplied_set"
    assert out("M4/projection")["result"]["selection"]["status"] == "inapplicable_for_declared_model"
    m8 = out("M8/projection")
    assert m8["result"]["raw_predictions"] == c0p["raw_predictions"]
    assert m8["provenance"] == {"calculation": "calculated_from_synthetic_assumptions",
        "observations_carried_not_used": 1, "physical_execution": "not_established"}

    refusals = [r for r in roles.values() if r["classification"] == "refusal"]
    assert len(refusals) == 11
    for row in refusals:
        value = out(row["role_id"])
        assert value["operation_status"] == "refused" and value["result"] is None
        assert value["diagnostics"] == sorted(value["diagnostics"], key=lambda x: (x["stage"], x["target"], x["code"]))
    assert out("F11-precedence")["diagnostics"][0]["code"] == "schema_required"

    probes = [r for r in roles.values() if r["classification"] == "resource_probe"]
    assert len(probes) == 26
    for dim, limit in manifest["proposed_limits_owner_approval_required"].items():
        assert out(f"G-{dim}-at")["status"] == "capacity_accept"
        plus = out(f"G-{dim}-plus-one")
        assert plus["status"] == "capacity_refuse"
        assert plus["diagnostics"][0]["target"] == f"/limits/{dim}"

    for key in package["public_producer_rehearsal"]["objects"].values():
        bundle = objects[key]["value"]
        kernel.ModelQueryMaterial.model_validate(bundle["material"])
        for result in bundle["results"].values():
            if isinstance(result, dict) and "material" in result:
                kernel.ModelQueryMaterial.model_validate(result["material"])

    print(json.dumps({"check_groups": 33, "objects_checked": len(objects),
                      "manifest_sha256": sha_bytes(manifest_raw),
                      "package_sha256": sha_bytes(package_raw),
                      "roles": len(roles)}, sort_keys=True, separators=(",", ":")))


def set_refs(value):
    found = set()
    stack = [value]
    while stack:
        item = stack.pop()
        if isinstance(item, dict):
            if set(item) == {"$ref"}:
                found.add(item["$ref"])
            else:
                stack.extend(item.values())
        elif isinstance(item, list):
            stack.extend(item)
    return found


if __name__ == "__main__":
    main()
